using System.Drawing.Imaging;
using System.Reflection;
using System.Text.Json;
namespace LeoLauncher;
static class InteractionBatchTests
{
    static IEnumerable<Control> Walk(Control root){foreach(Control c in root.Controls){yield return c;foreach(var nested in Walk(c))yield return nested;}}
    static void Show(Form form){form.StartPosition=FormStartPosition.Manual;form.Location=new(-19000,-19000);form.Show();Application.DoEvents();}
    static void Key(Control control,Keys key){typeof(Control).GetMethod("OnKeyDown",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(control,[new KeyEventArgs(key)]);}
    static void Capture(Form form,string file){using var image=new Bitmap(form.Width,form.Height);form.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(file);}
    public static void Run(string report){try{Directory.CreateDirectory(Path.GetDirectoryName(report)!);var checks=Check(Path.GetDirectoryName(report)!);File.WriteAllText(report,JsonSerializer.Serialize(new{ok=checks.Values.All(v=>v),checks},new JsonSerializerOptions{WriteIndented=true}));}catch(Exception e){File.WriteAllText(report,JsonSerializer.Serialize(new{ok=false,error=e.ToString()}));}}
    static Dictionary<string,bool> Check(string folder)
    {
        var c=new Dictionary<string,bool>();var file=Path.Combine(folder,"notes.json");if(File.Exists(file))File.Delete(file);var notes=new NoteStore(file);var first=notes.Save(null,"Alpha 第一条");var second=notes.Save(null,"Beta 第二条");var linked=notes.Save(null,"已关联比赛");notes.Link(linked.Id,"fixture-task");notes.Pin(first.Id,true);
        c["active_notes_exclude_linked_originals"]=notes.Query().Count==2;c["linked_notes_keep_original_text"]=notes.Query("比赛","linked").Single().Text==linked.Text;c["all_notes_include_both_groups"]=notes.Query(scope:"all").Count==3;c["note_search_ignores_case"]=notes.Query("ALPHA").Single().Id==first.Id;c["pinned_notes_sort_before_recent_notes"]=notes.Query()[0].Id==first.Id;notes.Save(first.Id,"Alpha 更新");c["editing_preserves_pin_and_identity"]=notes.Items.Single(n=>n.Id==first.Id).Pinned;c["pin_and_task_link_survive_reload"]=new NoteStore(file).Items.Any(n=>n.Id==first.Id&&n.Pinned)&&new NoteStore(file).Items.Any(n=>n.TaskId=="fixture-task");
        var legacy=JsonSerializer.Deserialize<StickyNote>("{\"Id\":\"old\",\"Text\":\"old note\",\"Created\":\"2026-10-19T00:00:00Z\",\"Updated\":\"2026-10-19T00:00:00Z\"}")!;c["legacy_notes_default_to_unpinned"]=!legacy.Pinned;
        var faultedStore=new NoteStore(Path.Combine(folder,Guid.NewGuid().ToString("N"),"notes.json"));try{faultedStore.Save(null,"keep me");c["failed_write_rolls_back_memory"]=false;}catch(IOException){c["failed_write_rolls_back_memory"]=faultedStore.Items.Count==0;}
        var quickStore=new NoteStore(null);using(var quick=new QuickNoteForm(quickStore)){Show(quick);Walk(quick).OfType<TextBox>().Single().Text="快捷记下的想法";Capture(quick,Path.Combine(folder,"quick-note.png"));((Button)quick.AcceptButton!).PerformClick();c["quick_entry_saves_once_and_closes"]=quickStore.Items.Single().Text=="快捷记下的想法"&&quick.IsDisposed;}
        using(var quick=new QuickNoteForm(quickStore)){Show(quick);Walk(quick).OfType<TextBox>().Single().Text="Esc 应丢弃这一句";EscapeWindows.Dismiss(quick);c["quick_entry_escape_does_not_save"]=quickStore.Items.Count==1;}
        using(var quick=new QuickNoteForm(faultedStore)){Show(quick);var input=Walk(quick).OfType<TextBox>().Single();input.Text="写入失败仍保留";((Button)quick.AcceptButton!).PerformClick();c["quick_entry_failure_keeps_text_and_window"]=!quick.IsDisposed&&input.Text=="写入失败仍保留"&&faultedStore.Items.Count==0;quick.Close();}
        using(var form=new NotesForm(notes,(n,d)=>"test-task")){Show(form);var search=Walk(form).OfType<TextBox>().Single(t=>t.AccessibleName=="便签搜索");var filter=Walk(form).OfType<ComboBox>().Single();var list=Walk(form).OfType<ListBox>().Single();c["note_window_starts_in_active_group"]=list.Items.Count==2;search.Text="ALPHA";c["note_window_filters_immediately"]=list.Items.Count==1;search.Clear();filter.SelectedIndex=1;c["note_window_has_separate_linked_group"]=list.Items.Count==1&&((StickyNote)list.Items[0]).TaskId!=null;filter.SelectedIndex=2;list.SelectedItem=list.Items.Cast<StickyNote>().Single(n=>n.Id==second.Id);Key(list,Keys.Enter);c["note_list_enter_focuses_editor"]=Walk(form).OfType<TextBox>().Single(t=>t.AccessibleName=="便签正文").Focused;Capture(form,Path.Combine(folder,"notes-organized.png"));form.Close();}
        var defaults=LeoHotkeys.Values(new Preferences());c["quick_note_has_configurable_fourth_hotkey"]=defaults.Length==4&&defaults[3]==(Keys.Control|Keys.Alt|Keys.N);var active=defaults.Select((value,index)=>(value,index)).ToDictionary(x=>x.index+1,x=>x.value);var desired=defaults.ToArray();desired[3]=Keys.Control|Keys.Alt|Keys.F10;try{LeoHotkeys.Replace(defaults,desired,id=>active.Remove(id),(id,key)=>{if(id==4&&key==desired[3])return false;active[id]=key;return true;});c["fourth_hotkey_conflict_restores_all_bindings"]=false;}catch(InvalidOperationException){c["fourth_hotkey_conflict_restores_all_bindings"]=active.Count==4&&Enumerable.Range(1,4).All(id=>active[id]==defaults[id-1]);}
        using(var oldSettings=JsonDocument.Parse("{\"VoiceHotkey\":\"unused\"}".Replace("\"unused\"",((int)(Keys.Control|Keys.Alt|Keys.N)).ToString()))){var legacyPrefs=oldSettings.RootElement.Deserialize<Preferences>()!;QuickNoteCompatibility.Migrate(oldSettings.RootElement,legacyPrefs);c["old_shortcut_is_not_stolen_by_new_default"]=legacyPrefs.QuickNoteHotkey==Keys.None&&legacyPrefs.VoiceHotkey==(Keys.Control|Keys.Alt|Keys.N);}
        var profile=UsageProfiles.Capture(new Preferences(),"速记方案");c["profiles_roundtrip_quick_note_hotkey"]=UsageProfiles.Prepare(profile,new Preferences()).QuickNoteHotkey==defaults[3];c["companion_profile_disables_quick_note_hotkey"]=UsageProfiles.Prepare(UsageProfiles.Templates()[0],new Preferences()).QuickNoteHotkey==Keys.None;
        var area=new Rectangle(-1600,0,1600,900);c["window_clamp_supports_negative_monitor_coordinates"]=area.Contains(WindowInteraction.KeepVisible(new(3000,-1000,600,500),area));var petBounds=new Rectangle(-500,200,130,145);var dialog=WindowInteraction.PlaceDialog(new(480,330),new(-700,150,650,550),petBounds,area);c["modal_placement_is_visible_and_avoids_pet"]=area.Contains(new Rectangle(dialog,new Size(480,330)))&&!new Rectangle(dialog,new Size(480,330)).IntersectsWith(petBounds);
        using(var form=new BarcaWindow{ClientSize=new(300,200),StartPosition=FormStartPosition.Manual,Location=new(-19000,-19000),TopMost=true}){WindowInteraction.Prepare(form);c["ordinary_window_is_not_always_on_top"]=!form.TopMost;Show(form);form.WindowState=FormWindowState.Minimized;WindowInteraction.Show(form);c["show_restores_minimized_window"]=form.WindowState==FormWindowState.Normal;form.Close();}
        using(var form=new Form()){var list=new ListBox();list.Items.AddRange(["A","B"]);list.SelectedIndex=1;form.Controls.Add(list);int accepted=0;SelectionKeys.Wire(list,()=>accepted++);Key(list,Keys.Enter);Key(list,Keys.Left);c["selection_enter_accepts_but_arrows_do_not_execute"]=accepted==1;}
        var seen=new List<FeatureFailure>();FeatureFaults.Observer=f=>seen.Add(f);bool recovered=false;bool failed=FeatureFaults.Run("fixture-module",()=>throw new IOException("secret payload must not be recorded"),()=>recovered=true);bool healthy=FeatureFaults.Run("fixture-healthy",()=>{});c["one_feature_failure_does_not_block_next_action"]=!failed&&healthy&&recovered;c["diagnostics_do_not_store_exception_message"]=seen.Single().ErrorType==nameof(IOException)&&!JsonSerializer.Serialize(seen).Contains("secret payload");
        using(var timer=new System.Windows.Forms.Timer()){FeatureFaults.Timer(timer,"fixture-poller",()=>throw new InvalidOperationException());timer.Start();typeof(System.Windows.Forms.Timer).GetMethod("OnTick",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(timer,[EventArgs.Empty]);c["faulty_poller_stops_instead_of_error_loop"]=!timer.Enabled;}
        var observerStore=new NoteStore(null);observerStore.Changed+=()=>throw new IOException("observer failure");observerStore.Save(null,"saved despite broken view");c["broken_view_observer_cannot_undo_successful_save"]=observerStore.Items.Count==1;
        using(var broken=new BarcaWindow()){Show(broken);FeatureFaults.HandleUi(new InvalidOperationException(),broken);c["known_faulty_window_can_be_disposed_independently"]=broken.IsDisposed;}
        using(var repeated=new BarcaWindow()){Show(repeated);FeatureFaults.HandleUi(new IOException(),repeated,false);c["first_ui_error_does_not_close_an_unrelated_window"]=!repeated.IsDisposed;FeatureFaults.HandleUi(new IOException(),repeated,false);c["repeated_ui_error_quarantines_only_affected_window"]=repeated.IsDisposed;}
        c["native_or_process_fatal_errors_are_not_claimed_recoverable"]=!FeatureFaults.Recoverable(new AccessViolationException())&&!FeatureFaults.Recoverable(new AggregateException(new OutOfMemoryException()));FeatureFaults.Observer=null;
        using(var sprites=new DockSprites()){foreach(var side in new[]{DockSide.Left,DockSide.Right}){using var near=new Bitmap(192,208);using var end=new Bitmap(192,208);using(var g=Graphics.FromImage(near)){g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;sprites.Draw(g,near.Size,.999f,side,0,positionProgress:.999f);}using(var g=Graphics.FromImage(end)){g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;sprites.Draw(g,end.Size,1,side,0,positionProgress:1);}long delta=0;for(int y=0;y<208;y++)for(int x=0;x<192;x++){var a=near.GetPixel(x,y);var b=end.GetPixel(x,y);delta+=Math.Abs(a.A-b.A)+Math.Abs(a.R-b.R)+Math.Abs(a.G-b.G)+Math.Abs(a.B-b.B);}c[side+"_final_frame_has_no_visual_jump"]=delta/(192d*208*4)<.2;end.Save(Path.Combine(folder,side+"-settled.png"));}}
        using(var pet=new PetForm(new Preferences{ApplicationIndexing=false},true)){pet.Show();Application.DoEvents();foreach(var pair in pet.VerifyDockFaultIsolation())c[pair.Key]=pair.Value;pet.Close();}
        return c;
    }
}
sealed partial class PetForm
{
    internal Dictionary<string,bool> VerifyDockFaultIsolation(){var c=new Dictionary<string,bool>();RevealDock(true);dockSprites=new DockSprites();dockSprites.Dispose();dockSide=DockSide.Left;dockMotion.BeginTuck(0);for(int t=32;t<=1000;t+=32)dockMotion.Tick(t,true,false);using var surface=RenderPetSurface();c["bad_dock_asset_falls_back_to_normal_pet"]=dockDisabled&&dockMotion.Progress==0&&surface.Width==Width;c["dock_failure_keeps_footer_and_hit_target_usable"]=foot.Visible&&hit.Bounds==Bounds;ShowTodos();c["another_feature_opens_after_dock_failure"]=todoWindow?.Visible==true;todoWindow?.Close();return c;}
}
